// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint64 ts1, uint64 ts2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(ts1 > 0 && ts2 > ts1);

        // first call at ts1
        vm.warp(ts1);
        vm.roll(1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        assertTrue(c.pastBlockTime() == ts1);

        // second call at ts2: admissible since ts2 > pastBlockTime
        vm.warp(ts2);
        vm.roll(16);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok2);

        // General rule: after any successful call, pastBlockTime equals that call's block.timestamp
        assertTrue(c.pastBlockTime() == ts2);
    }
}
